<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap.php';
Auth::requireRole('admin');
$pdo = db();
$today = new DateTimeImmutable('today');
$from = (string)($_GET['from'] ?? $today->modify('-29 days')->format('Y-m-d'));
$to = (string)($_GET['to'] ?? $today->format('Y-m-d'));
$validDate = static fn(string $v): bool => (bool)preg_match('/^\d{4}-\d{2}-\d{2}$/', $v) && DateTimeImmutable::createFromFormat('!Y-m-d', $v) !== false;
if (!$validDate($from) || !$validDate($to) || $from > $to || (new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->days > 366) {
    http_response_code(400); exit('Invalid date range. Choose a range of up to 367 days.');
}
$start = $from . ' 00:00:00'; $end = (new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d') . ' 00:00:00';
$summary = $pdo->prepare('SELECT COUNT(*) orders_count, COALESCE(SUM(total),0) order_value FROM orders WHERE created_at >= ? AND created_at < ?');
$summary->execute([$start,$end]); $orders = $summary->fetch() ?: ['orders_count'=>0,'order_value'=>0];
$payments = $pdo->prepare('SELECT COUNT(*) payment_count, COALESCE(SUM(amount),0) paid_amount FROM payments WHERE status = \'success\' AND created_at >= ? AND created_at < ?');
$payments->execute([$start,$end]); $paid = $payments->fetch() ?: ['payment_count'=>0,'paid_amount'=>0];
$newUsers = $pdo->prepare('SELECT COUNT(*) FROM users WHERE created_at >= ? AND created_at < ?'); $newUsers->execute([$start,$end]);
$top = $pdo->prepare('SELECT p.name, SUM(oi.quantity) units, SUM(oi.subtotal) item_value FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN products p ON p.id=oi.product_id WHERE o.created_at >= ? AND o.created_at < ? AND o.status NOT IN (\'cancelled\',\'refunded\') GROUP BY p.id,p.name ORDER BY units DESC,item_value DESC LIMIT 10');
$top->execute([$start,$end]); $topProducts=$top->fetchAll();
$monthlyChart=[];
$monthlyStmt=$pdo->prepare("SELECT DATE_FORMAT(created_at,'%Y-%m') period, COUNT(*) total FROM orders WHERE created_at >= ? AND created_at < ? GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY period");
$monthlyStmt->execute([$start,$end]); $monthlyChart=$monthlyStmt->fetchAll(PDO::FETCH_ASSOC);
$maxMonthly=max(1,...array_map(static fn($r)=>(int)$r['total'],$monthlyChart ?: [['total'=>0]]));
$active='reports'; $pageTitle='Business reports'; $pageDescription='Date-filtered marketplace activity';
?>
