order-collapse:collapse}.rp-table th,.rp-table td{text-align:left;padding:12px 16px;border-bottom:1px solid #edf2f7;font-size:.75rem}.rp-table th{font-size:.65rem;text-transform:uppercase;letter-spacing:.07em;color:#94a3b8;background:#fbfdff}.rp-table tr:last-child td{border-bottom:0}.rp-money{font-weight:850}.rp-insight{padding:18px}.rp-stat{padding:13px 0;border-bottom:1px solid #edf2f7}.rp-stat:last-child{border-bottom:0}.rp-stat label{display:block;font-size:.68rem;color:#94a3b8}.rp-stat strong{display:block;margin-top:3px;font-size:1rem}.rp-empty{padding:30px;text-align:center;color:#94a3b8;font-size:.8rem}@media(max-width:1050px){.rp-kpis{grid-template-columns:repeat(3,1fr)}.rp-layout{grid-template-columns:1fr}}@media(max-width:700px){.rp-hero{align-items:flex-start;flex-direction:column}.rp-filter{grid-template-columns:1fr 1fr}.rp-filter .rp-btn{grid-column:span 1}.rp-kpis{grid-template-columns:1fr 1fr}.rp-table{min-width:650px}.rp-panel{overflow:auto}.rp-table th,.rp-table td{white-space:nowrap}}@media(max-width:460px){.rp-kpis{grid-template-columns:1fr}.rp-filter{grid-template-columns:1fr}}
</style></head><body class="admin-shell rp"><?php require __DIR__.'/../partials/admin_sidebar.php'; ?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php'; ?><main class="admin-content"><div class="rp-hero"><div><div class="rp-kicker">Business intelligence</div><h1>Marketplace reports</h1><p class="rp-sub">A management view of orders, payments, customers and product performance.</p></div><div class="rp-period"><?=e($from)?> — <?=e($to)?></div></div>
<section class="panel-df" style="margin-bottom:18px"><div class="panel-body-df"><form class="rp-filter" method="get"><label>From<input type="date" name="from" value="<?=e($from)?>" required></label><label>To<input type="date" name="to" value="<?=e($to)?>" required></label><button class="rp-btn rp-primary" type="submit">Generate report</button><a class="rp-btn rp-secondary" href="<?=url('/admin/reports.php')?>">Last 30 days</a></form><p class="rp-note">Order value uses order totals. Successful payment amount uses successful payment records; refunds and gateway fees are not netted out.</p></div></section>
<section class="rp-kpis"><article class="rp-kpi"><span>Orders created</span><strong><?=number_format((int)$orders['orders_count'])?></strong><small>Selected period</small></article><article class="rp-kpi"><span>Order value</span><strong>GH₵ <?=number_format((float)$orders['order_value'],2)?></strong><small>Gross order totals</small></article><article class="rp-kpi"><span>Successful payments</span><strong><?=number_format((int)$paid['payment_count'])?></strong><small>Confirmed records</small></article><article class="rp-kpi"><span>Paid amount</span><strong>GH₵ <?=number_format((float)$paid['paid_amount'],2)?></strong><small>Successful payments</small></article><article class="rp-kpi"><span>New accounts</span><strong><?=number_format((int)$newUsers->fetchColumn())?></strong><small>Users created</small></article></section>
<section class="rp-panel" style="margin-bottom:18px;padding:18px"><div class="rp-head"><h2>Orders over time</h2><span>Selected date range</span></div><div style="display:flex;align-items:flex-end;gap:10px;min-height:180px;padding:20px 8px 0;border-bottom:1px solid #e2e8f0;overflow-x:auto"><?php if($monthlyChart): foreach($monthlyChart as $m): $barHeight=max(4,(int)round(((int)$m['total']/$maxMonthly)*130));?><div title="<?=e($m['period'])?>: <?=number_format((int)$m['total'])?> orders" style="min-width:54px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:8px;height:160px"><strong style="font-size:.72rem;color:#0b2545"><?=number_format((int)$m['total'])?></strong><div style="height:<?=$barHeight?>px;width:28px;border-radius:7px 7px 0 0;background:#0787df"></div><small style="font-size:.65rem;color:#64748b"><?=e(date('M y',strtotime($m['period'].'-01')))?></small></div><?php endforeach; else:?><p style="color:#64748b;font-size:.85rem">No orders in the selected period to chart.</p><?php endif;?></div></section>
<section class="rp-layout"><article class="rp-panel"><div class="rp-head"><h2>Top products by units ordered</h2><span>Top 10</span></div><?php if($topProducts): ?><div style="overflow:auto"><table class="rp-table"><thead><tr><th>#</th><th>Product</th><th>Units</th><th>Item value</th></tr></thead><tbody><?php foreach($topProducts as $i=>$row):?><tr><td><?=($i+1)?></td><td><strong><?=e($row['name'])?></strong></td><td><?=number_format((int)$row['units'])?></td><td class="rp-money">GH₵ <?=number_format((float)$row['item_value'],2)?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="rp-empty">No product activity in this date range.</div><?php endif;?></article><aside class="rp-panel"><div class="rp-head"><h2>Report notes</h2><span>Context</span></div><div class="rp-insight"><div class="rp-stat"><label>Reporting window</label><strong><?=e((new DateTimeImmutable($from))->format('d M Y'))?> — <?=e((new DateTimeImmutable($to))->format('d M Y'))?></strong></div><div class="rp-stat"><label>Payment basis</label><strong>Successful payment records</strong></div><div class="rp-stat"><label>Order basis</label><strong>Orders created in period</strong></div><div class="rp-stat"><label>Top-product basis</label><strong>Units ordered, then item value</strong></div></div></aside></section></main></section></body></html>